import { applyTemplateFor, planTemplateFor, regenerateTemplateFor } from './templates.ts';
import { PROJECT_RESOURCE_KINDS, registerResourcesAndPrompts } from './mcpResources.ts';
import type { Derivatives } from './derive.ts';
import { cancelTrackingJob, motionTrackView, startTrackingJob } from './tracking.ts';
import { cameraMotionView, cancelStabiliseJob, startStabiliseJob } from './stabilise.ts';
import { STABILISE_JOB_TYPE, StabiliseRunBodySchema } from '@pulseframe/core';
import { CreditsQuerySchema, LibraryUseBodySchema } from '@pulseframe/core';
import { libraryError } from './library/contract.ts';
import { creditsFor } from './library/credits.ts';
import { useLibraryItemFor } from './library/routes.ts';
import { MadeRenderRequestSchema } from '@pulseframe/core';
import { madeError } from './made/contract.ts';
import { FindQuerySchema } from '@pulseframe/core';
import { findTextFor } from './craft/findText.ts';
import { pearlsView } from './pearls.ts';
import { audienceChangesFor } from './audiences/routes.ts';
import { applyMusicFitFor, planMusicFitFor } from './musicfit/routes.ts';
import { MusicFitApplyRequestSchema, MusicFitPlanRequestSchema } from '@pulseframe/core';
import { multicamView, syncMulticam } from './multicamSync.ts';
import { takeFor } from './perform.ts';
import { cancelMomentsJob, momentsLaneOf, startMomentsJob } from './moments.ts';
import { cancelStillsJob, readSharpFrames, startStillsJob, stillsReady, withStillsErrors } from './stills.ts';
import { FindSharpBodySchema, ReadSharpQuerySchema, STILLS_JOB_TYPE, STILLS_LABEL, STILLS_MAX_RANGE_FRAMES } from '@pulseframe/core';
import { assertMayTakeRendered, forPrincipal, peopleAccess, peopleNote, readingAs } from './peoplePrivacy.ts';
import { assertMayHandleImportJob, IMPORT_JOB_TYPE, type ImportQueue } from './importContracts.ts';
import type { RenderCacheService } from './renderCacheRoutes.ts';
import type { AssistantJobControls } from './assistant/routes.ts';
